import React, { useState, useMemo, useEffect, useRef } from 'react';

interface VentanillaMetadata {
  sedes: string[];
  ambitos: string[];
  users: string[];
  procedimientos: string[];
  procedimientos_tupa: number[];
  procedimientos_notupa: number[];
  dest_sedes: string[];
  dest_grupos: string[];
  dest_oficinas: string[];
}

type VentanillaRecordTuple = [
  number, // 0: origen (0=digital, 1=fisico)
  number, // 1: clasif (0=nuevo, 1=anexo)
  number, // 2: tupa (0=tupa, 1=notupa)
  number, // 3: est_d (0=derivado, 1=archivado, 2=calidad, 3=observado)
  number, // 4: est_c (0=atendido, 1=pendiente, 2=anulado, 3=observado)
  number, // 5: s_idx (sede index)
  number, // 6: a_idx (ambito index)
  number, // 7: u_idx (user index)
  string, // 8: date_str (YYYY-MM-DD)
  number | null, // 9: val_h (validation hours)
  number, // 10: p_idx (procedimiento index)
  number, // 11: dest_s_idx
  number, // 12: dest_g_idx
  number  // 13: dest_o_idx
];

interface VentanillaDashboardData {
  metadata: VentanillaMetadata;
  records: VentanillaRecordTuple[];
}

interface InternoMetadata {
  grupos: string[];
  grupo_oficinas: string[];
  ultimo_sedes: string[];
  ultimo_escritorios: string[];
  bandejas: string[];
  procedimientos: string[];
  dates: string[];
  cuts?: string[];
  plazos: string[];
}

type InternoRecordTuple = [
  number, // 0: sede_code (0=SC, 1=OD)
  number, // 1: organo_idx (which maps to grupos)
  number, // 2: goIdx (grupo_oficinas)
  number, // 3: usIdx (ultimo_sedes)
  number, // 4: ueIdx (ultimo_escritorios)
  number, // 5: tupa_code (0=TUPA, 1=NO TUPA)
  number, // 6: proc_idx
  number, // 7: creation_year
  number, // 8: ingreso_year
  number, // 9: bandeja_idx
  number, // 10: date_idx
  number, // 11: origen_code (0=interno, 1=externo)
  number, // 12: cut_idx
  number, // 13: plazo_idx
  number  // 14: dias_transcurridos
];

interface InternoDashboardData {
  metadata: InternoMetadata;
  records: InternoRecordTuple[];
}

interface ExecutiveDashboardProps {
  data: VentanillaDashboardData;
}

// Year configuration options (2014 to 2026)
const YEAR_OPTIONS = Array.from({ length: 13 }, (_, i) => 2014 + i);

// Helper to classify TUPA procedures by silence type
const getSilenceType = (procName: string): 'SAP' | 'SAN' => {
  const name = procName.toLowerCase();
  if (
    name.includes('acceso a la inform') ||
    name.includes('reconocimiento') ||
    name.includes('inspección ocular') ||
    name.includes('inspeccin ocular') ||
    name.includes('prórroga') ||
    name.includes('prrroga') ||
    name.includes('copia') ||
    name.includes('duplicado')
  ) {
    return 'SAP'; // Silencio Positivo (+)
  }
  return 'SAN'; // Silencio Negativo (-)
};

